import{_ as r,o,c as n,ah as s}from"./chunks/framework.DjU4PSOm.js";const c=JSON.parse('{"title":"","description":"","frontmatter":{"tags":["philosophy/Ethics"],"date":"2026-10-19T00:00:00.000Z"},"headers":[{"level":2,"title":"📢 중간고사 공지 (수업 맨 앞)","slug":"📢-중간고사-공지-수업-맨-앞","link":"#📢-중간고사-공지-수업-맨-앞","children":[{"level":3,"title":"수업 끝부분 — 에세이 답안 구성 요령 (자막 364~391, 시험 대비로 중요)","slug":"수업-끝부분-—-에세이-답안-구성-요령-자막-364-391-시험-대비로-중요","link":"#수업-끝부분-—-에세이-답안-구성-요령-자막-364-391-시험-대비로-중요","children":[]}]},{"level":2,"title":"1. 앞 시간 마무리 — 선호 vs 행동 (정독 전, 슬라이드 15쪽 흐름)","slug":"_1-앞-시간-마무리-—-선호-vs-행동-정독-전-슬라이드-15쪽-흐름","link":"#_1-앞-시간-마무리-—-선호-vs-행동-정독-전-슬라이드-15쪽-흐름","children":[]},{"level":2,"title":"2. 『공리주의』 2장 정독 — 첫 문단 마지막 문장 (슬라이드 17쪽)","slug":"_2-『공리주의』-2장-정독-—-첫-문단-마지막-문장-슬라이드-17쪽","link":"#_2-『공리주의』-2장-정독-—-첫-문단-마지막-문장-슬라이드-17쪽","children":[]},{"level":2,"title":"3. 정독 — 두 번째 단락 (슬라이드 17~19쪽)","slug":"_3-정독-—-두-번째-단락-슬라이드-17-19쪽","link":"#_3-정독-—-두-번째-단락-슬라이드-17-19쪽","children":[{"level":3,"title":"(1) \\"쾌락의 질의 차이란 무엇인가 … 단지 양이 더 많다는 것 말고 … 가능한 답은 하나뿐\\" — 가장 어려운 개념적 질문","slug":"_1-쾌락의-질의-차이란-무엇인가-단지-양이-더-많다는-것-말고-가능한-답은-하나뿐-—-가장-어려운-개념적-질문","link":"#_1-쾌락의-질의-차이란-무엇인가-단지-양이-더-많다는-것-말고-가능한-답은-하나뿐-—-가장-어려운-개념적-질문","children":[]},{"level":3,"title":"(2) \\"두 쾌락 중 둘을 모두 경험한 사람 전부 또는 거의 전부가 도덕적 의무감과 무관하게 분명히 선호하는 쪽이 있다면, 그것이 더 바람직한 쾌락이다\\" — 유능한 판단자 시험의 첫 정식","slug":"_2-두-쾌락-중-둘을-모두-경험한-사람-전부-또는-거의-전부가-도덕적-의무감과-무관하게-분명히-선호하는-쪽이-있다면-그것이-더-바람직한-쾌락이다-—-유능한-판단자-시험의-첫-정식","link":"#_2-두-쾌락-중-둘을-모두-경험한-사람-전부-또는-거의-전부가-도덕적-의무감과-무관하게-분명히-선호하는-쪽이-있다면-그것이-더-바람직한-쾌락이다-—-유능한-판단자-시험의-첫-정식","children":[]},{"level":3,"title":"(3) \\"더 큰 불만을 동반한다는 것을 알면서도\\" 선호한다 — 고급 쾌락의 비용","slug":"_3-더-큰-불만을-동반한다는-것을-알면서도-선호한다-—-고급-쾌락의-비용","link":"#_3-더-큰-불만을-동반한다는-것을-알면서도-선호한다-—-고급-쾌락의-비용","children":[]},{"level":3,"title":"(4) \\"그 대신 다른 쾌락을 어떤 양으로도 포기하지 않으려 한다\\" — 매우 강한 주장","slug":"_4-그-대신-다른-쾌락을-어떤-양으로도-포기하지-않으려-한다-—-매우-강한-주장","link":"#_4-그-대신-다른-쾌락을-어떤-양으로도-포기하지-않으려-한다-—-매우-강한-주장","children":[]},{"level":3,"title":"(5) \\"우리는 선호되는 즐거움에 질의 우월성을 귀속시킬 자격이 있다\\" — 결론은 인식론적","slug":"_5-우리는-선호되는-즐거움에-질의-우월성을-귀속시킬-자격이-있다-—-결론은-인식론적","link":"#_5-우리는-선호되는-즐거움에-질의-우월성을-귀속시킬-자격이-있다-—-결론은-인식론적","children":[]}]},{"level":2,"title":"4. 유능한 판단자 시험의 해부 (슬라이드 13·18~19쪽 보강, 자막 107~130)","slug":"_4-유능한-판단자-시험의-해부-슬라이드-13·18-19쪽-보강-자막-107-130","link":"#_4-유능한-판단자-시험의-해부-슬라이드-13·18-19쪽-보강-자막-107-130","children":[]},{"level":2,"title":"5. 밀에 대한 주요 반론 (슬라이드 20쪽)","slug":"_5-밀에-대한-주요-반론-슬라이드-20쪽","link":"#_5-밀에-대한-주요-반론-슬라이드-20쪽","children":[{"level":3,"title":"① 순환성 (circularity)","slug":"_1-순환성-circularity","link":"#_1-순환성-circularity","children":[]},{"level":3,"title":"② 자격 있는 판단자들 사이의 지속적 불일치 → 다원주의 해석","slug":"_2-자격-있는-판단자들-사이의-지속적-불일치-→-다원주의-해석","link":"#_2-자격-있는-판단자들-사이의-지속적-불일치-→-다원주의-해석","children":[]},{"level":3,"title":"③ 이론적 불안정성 — 쾌락주의 vs 완전주의","slug":"_3-이론적-불안정성-—-쾌락주의-vs-완전주의","link":"#_3-이론적-불안정성-—-쾌락주의-vs-완전주의","children":[]},{"level":3,"title":"④ 적응적 선호와 불평등한 접근","slug":"_4-적응적-선호와-불평등한-접근","link":"#_4-적응적-선호와-불평등한-접근","children":[]},{"level":3,"title":"⑤ 엘리트주의와 \\"고급/저급\\" 어휘의 오용 → 참여 방식(mode of engagement) 으로 읽기","slug":"_5-엘리트주의와-고급-저급-어휘의-오용-→-참여-방식-mode-of-engagement-으로-읽기","link":"#_5-엘리트주의와-고급-저급-어휘의-오용-→-참여-방식-mode-of-engagement-으로-읽기","children":[]}]},{"level":2,"title":"6. 현대 적용 (슬라이드 21~24쪽)","slug":"_6-현대-적용-슬라이드-21-24쪽","link":"#_6-현대-적용-슬라이드-21-24쪽","children":[{"level":3,"title":"디지털 플랫폼 (21쪽)","slug":"디지털-플랫폼-21쪽","link":"#디지털-플랫폼-21쪽","children":[]},{"level":3,"title":"교육 (22쪽)","slug":"교육-22쪽","link":"#교육-22쪽","children":[]},{"level":3,"title":"직장과 지표 (23쪽)","slug":"직장과-지표-23쪽","link":"#직장과-지표-23쪽","children":[]},{"level":3,"title":"사회와 정책 (24쪽)","slug":"사회와-정책-24쪽","link":"#사회와-정책-24쪽","children":[]}]},{"level":2,"title":"7. 밀식 분석 5단계 (슬라이드 25쪽; 자막은 356~363부터 끊긴 부분 포함)","slug":"_7-밀식-분석-5단계-슬라이드-25쪽-자막은-356-363부터-끊긴-부분-포함","link":"#_7-밀식-분석-5단계-슬라이드-25쪽-자막은-356-363부터-끊긴-부분-포함","children":[]},{"level":2,"title":"8. 철학자 비교와 최종 종합 (슬라이드 26쪽, 자막 369~404)","slug":"_8-철학자-비교와-최종-종합-슬라이드-26쪽-자막-369-404","link":"#_8-철학자-비교와-최종-종합-슬라이드-26쪽-자막-369-404","children":[{"level":3,"title":"한눈에 비교","slug":"한눈에-비교","link":"#한눈에-비교","children":[]},{"level":3,"title":"최종 종합","slug":"최종-종합","link":"#최종-종합","children":[]},{"level":3,"title":"밀의 논증 재구성 (6단계, 자막 405~415 — 시험에서 그대로 쓸 수 있는 골격)","slug":"밀의-논증-재구성-6단계-자막-405-415-—-시험에서-그대로-쓸-수-있는-골격","link":"#밀의-논증-재구성-6단계-자막-405-415-—-시험에서-그대로-쓸-수-있는-골격","children":[]}]},{"level":2,"title":"시험 대비 핵심 키워드 (이 노트 기준)","slug":"시험-대비-핵심-키워드-이-노트-기준","link":"#시험-대비-핵심-키워드-이-노트-기준","children":[]}],"relativePath":"philosophy/Ethics/16. 유능한 판단자 시험, 밀에 대한 반론, 밀식 분석 5단계(7주차-2).md","filePath":"philosophy/Ethics/16. 유능한 판단자 시험, 밀에 대한 반론, 밀식 분석 5단계(7주차-2).md"}'),g={name:"philosophy/Ethics/16. 유능한 판단자 시험, 밀에 대한 반론, 밀식 분석 5단계(7주차-2).md"};function l(i,t,e,a,u,h){return o(),n("div",null,[...t[0]||(t[0]=[s('<blockquote><p>📎 <strong>슬라이드 위치</strong>: <code>26-2 Ethics-Week-7.pdf</code> / <code>26-2 윤리학 7강.pdf</code> 17~26쪽 (정독 17~19쪽 두 번째 단락 ~ 주요 반론 20쪽 ~ 현대 적용 21~24쪽 ~ 밀식 분석 5단계 25쪽 ~ 최종 종합 26쪽). 앞 시간은 <a href="./15. 밀의 질적 공리주의 — 유능한 판단자와 『공리주의』 2장 정독(7주차).html">15. 밀의 질적 공리주의 — 유능한 판단자와 『공리주의』 2장 정독(7주차)</a>.</p></blockquote><h2 id="📢-중간고사-공지-수업-맨-앞" tabindex="-1">📢 중간고사 공지 (수업 맨 앞) <a class="header-anchor" href="#📢-중간고사-공지-수업-맨-앞" aria-label="Permalink to &quot;📢 중간고사 공지 (수업 맨 앞)&quot;">​</a></h2><ul><li><strong>날짜·장소</strong>: <strong>10월 23일(금)</strong>, <strong>이 강의실</strong>.</li><li><strong>시간</strong>: <strong>오후 3:00 ~ 4:15</strong>. <strong>3:05까지는 강의실에 도착</strong>해야 한다.</li><li><strong>형식</strong>: <strong>에세이 문제 2개</strong>. 수업에서 다룬 <strong>핵심 개념·이론에 대한 이해를 설명</strong>하고 <strong>문제에 대한 자신의 관점을 세워 논리적으로 정당화</strong>하라는 문제.</li><li><strong>부정행위</strong>: 엄격히 금지, 적발 시 <strong>F 학점</strong>.</li><li><strong>세부 지침은 이미 LMS에 업로드</strong>되어 있으니 <strong>꼼꼼히 확인</strong>할 것. 질문 받음.</li><li><strong>10월 26일(월)은 수업 없음.</strong></li><li>자막 속 &quot;Milton exam&quot;은 <strong>midterm exam</strong> 오인식.</li></ul><h3 id="수업-끝부분-—-에세이-답안-구성-요령-자막-364-391-시험-대비로-중요" tabindex="-1">수업 끝부분 — 에세이 답안 구성 요령 (자막 364~391, <strong>시험 대비로 중요</strong>) <a class="header-anchor" href="#수업-끝부분-—-에세이-답안-구성-요령-자막-364-391-시험-대비로-중요" aria-label="Permalink to &quot;수업 끝부분 — 에세이 답안 구성 요령 (자막 364~391, **시험 대비로 중요**)&quot;">​</a></h3><p>모범 답안은 <strong>단계적으로</strong> 쓴다:</p><ol><li><strong>밀과 공리주의의 연속성</strong>을 밝힌다 — <strong>결과, 일반 행복, 쾌락, 공정성</strong>.</li><li><strong>왜 양만으로는 부족한지</strong> 설명한다.</li><li><strong>유능한 판단자</strong>를 정확히 제시한다 — <strong>두 쾌락 모두의 경험, 확정된 선호, 단순한 도덕적 의무감의 배제</strong>.</li><li><strong>상황적 이점 vs 내재적 질적 우월성</strong>을 구별한다.</li><li><strong>평가</strong>: 최소 <strong>두 가지 문제</strong>를 짚는다 — <strong>엘리트주의/문화적 위계, 유능한 판단자 시험의 순환성, 자격 있는 판단자들 사이의 불일치, 적응적 선호와 불평등한 접근, 쾌락주의-완전주의 긴장</strong>.</li><li>마지막으로 <strong>구체적 사례에 적용</strong>하되 <strong>어떤 특징이 양적이고 어떤 것이 질적인지, 어떤 추가 증거가 필요한지</strong>를 정확히 보인다. <strong>분석 없이 &quot;이쪽이 더 높다&quot;고 선언하지 말 것.</strong></li></ol><p><strong>좋은 답안의 조건</strong>: 기준을 <strong>명시</strong>하고, <strong>빠진 증거</strong>를 짚고, <strong>이 틀 자체가 해결하지 못하는 질문</strong>이 어디인지 인식한다.</p><p><strong>두 가지 흔한 오류 (5단계 분석의 경고, 슬라이드 25쪽)</strong>: ① 문화적으로 위세가 있다는 이유만으로 활동을 &quot;고급&quot;이라 부르는 것 ② <strong>숫자가 무엇을 나타내는지 묻지 않고</strong> 공리주의를 <strong>수치 극대화로 환원</strong>하는 것.</p><hr><h2 id="_1-앞-시간-마무리-—-선호-vs-행동-정독-전-슬라이드-15쪽-흐름" tabindex="-1">1. 앞 시간 마무리 — 선호 vs 행동 (정독 전, 슬라이드 15쪽 흐름) <a class="header-anchor" href="#_1-앞-시간-마무리-—-선호-vs-행동-정독-전-슬라이드-15쪽-흐름" aria-label="Permalink to &quot;1. 앞 시간 마무리 — 선호 vs 행동 (정독 전, 슬라이드 15쪽 흐름)&quot;">​</a></h2><ul><li><strong>예시</strong>: 학생이 긴 하루 뒤 짧은 오락을 반복 선택하면서도, <strong>지속적인 독서가 더 만족스러운 성취</strong>라고 느낀다 → <strong>기록된 행동과 성찰적 선호는 갈라질 수 있다.</strong></li><li>이 구분은 <strong>클릭으로 사용자가 중시하는 것을 추론하는 추천 시스템</strong>에 밀을 적용할 때 핵심이다.</li><li><strong>토론</strong>: 행동과 맥락은 <strong>무엇이 바람직한가의 결정적 증거</strong>인가? 어떤 조건이면 사람들이 밀의 시험에 <strong>충분히 정보를 가진</strong> 것이라 할 수 있는가?</li></ul><h2 id="_2-『공리주의』-2장-정독-—-첫-문단-마지막-문장-슬라이드-17쪽" tabindex="-1">2. 『공리주의』 2장 정독 — 첫 문단 마지막 문장 (슬라이드 17쪽) <a class="header-anchor" href="#_2-『공리주의』-2장-정독-—-첫-문단-마지막-문장-슬라이드-17쪽" aria-label="Permalink to &quot;2. 『공리주의』 2장 정독 — 첫 문단 마지막 문장 (슬라이드 17쪽)&quot;">​</a></h2><ul><li><strong>&quot;다른 모든 것을 평가할 때는 질도 양과 함께 고려하면서 쾌락의 평가만 양에 달려 있다고 보는 것은 터무니없다.&quot;</strong></li><li>이것은 <strong>일상의 평가 관행에 호소</strong>하는 논증이다. 우리는 <strong>단위가 많다고 자동으로 더 좋다고 가정하지 않는다.</strong> <strong>질이 양의 의미를 바꿀 수 있다.</strong></li><li>요점은 <strong>숫자가 쓸모없다</strong>는 게 아니라 <strong>수치 척도가 경험을 가치 있게 만드는 차원을 대표하지 못할 수 있다</strong>는 것. <ul><li>예: <strong>산만한 5시간의 공부</strong>가 <strong>집중된 1시간의 이해</strong>보다 명백히 낫지 않다. <strong>저품질 정보 1,000개</strong>가 <strong>신뢰할 만한 설명 1개</strong>보다 낫지 않다.</li><li>공공 기관의 <strong>클릭·인용·방문자 수</strong>는 유용한 <strong>증거</strong>일 수 있지만 <strong>성공의 완전한 정의는 아니다.</strong></li></ul></li><li><strong>토론</strong>: 어떤 교육적 성과가 <strong>수치로 포착하기 어려운가?</strong> 측정은 <strong>언제 가치를 명확히 하고 언제 왜곡</strong>하는가?</li></ul><h2 id="_3-정독-—-두-번째-단락-슬라이드-17-19쪽" tabindex="-1">3. 정독 — 두 번째 단락 (슬라이드 17~19쪽) <a class="header-anchor" href="#_3-정독-—-두-번째-단락-슬라이드-17-19쪽" aria-label="Permalink to &quot;3. 정독 — 두 번째 단락 (슬라이드 17~19쪽)&quot;">​</a></h2><h3 id="_1-쾌락의-질의-차이란-무엇인가-단지-양이-더-많다는-것-말고-가능한-답은-하나뿐-—-가장-어려운-개념적-질문" tabindex="-1">(1) &quot;쾌락의 질의 차이란 무엇인가 … 단지 양이 더 많다는 것 말고 … 가능한 답은 하나뿐&quot; — <strong>가장 어려운 개념적 질문</strong> <a class="header-anchor" href="#_1-쾌락의-질의-차이란-무엇인가-단지-양이-더-많다는-것-말고-가능한-답은-하나뿐-—-가장-어려운-개념적-질문" aria-label="Permalink to &quot;(1) &quot;쾌락의 질의 차이란 무엇인가 … 단지 양이 더 많다는 것 말고 … 가능한 답은 하나뿐&quot; — **가장 어려운 개념적 질문**&quot;">​</a></h3><ul><li><strong>쾌락이 궁극적 선이라면, 양 말고 어떻게 한 쾌락이 더 나을 수 있는가?</strong></li><li><strong>&quot;merely as a pleasure&quot;</strong> 는 <strong>급여·명성·건강 같은 도구적 이익을 배제</strong>한다. 따라서 밀은 <strong>경험 자체 안에서 즐거움의 양식을 가르는 시험</strong>을 줘야 한다.</li><li><strong>&quot;merely as a pleasure&quot;의 강한 표현</strong>은 논증이 허락하는 것보다 <strong>더 강한 답</strong>(자율, 역량, 성취, 객관적 선)에 기댈 수도 있다. 그러나 밀의 <strong>경험주의 전략</strong> 안에서는 <strong>경험한 대안들의 비교가 질의 실제적 심판</strong>이 된다.</li><li><strong>토론</strong>: 밀은 <strong>질을 정의</strong>하고 있는가, 아니면 <strong>질을 알 수 있는 증거</strong>를 제시하는가? &quot;merely as a pleasure&quot;는 왜 <strong>쾌락주의 안의 긴장</strong>을 키우는가?</li></ul><h3 id="_2-두-쾌락-중-둘을-모두-경험한-사람-전부-또는-거의-전부가-도덕적-의무감과-무관하게-분명히-선호하는-쪽이-있다면-그것이-더-바람직한-쾌락이다-—-유능한-판단자-시험의-첫-정식" tabindex="-1">(2) &quot;두 쾌락 중 둘을 모두 경험한 사람 전부 또는 거의 전부가 도덕적 의무감과 무관하게 분명히 선호하는 쪽이 있다면, 그것이 더 바람직한 쾌락이다&quot; — <strong>유능한 판단자 시험의 첫 정식</strong> <a class="header-anchor" href="#_2-두-쾌락-중-둘을-모두-경험한-사람-전부-또는-거의-전부가-도덕적-의무감과-무관하게-분명히-선호하는-쪽이-있다면-그것이-더-바람직한-쾌락이다-—-유능한-판단자-시험의-첫-정식" aria-label="Permalink to &quot;(2) &quot;두 쾌락 중 둘을 모두 경험한 사람 전부 또는 거의 전부가 도덕적 의무감과 무관하게 분명히 선호하는 쪽이 있다면, 그것이 더 바람직한 쾌락이다&quot; — **유능한 판단자 시험의 첫 정식**&quot;">​</a></h3><ul><li><strong>두 대안의 경험</strong>이 필요하다 — <strong>비교는 친숙함을 요구</strong>하므로.</li><li>선호는 <strong>일시적이 아니라 확정적</strong>이어야 한다.</li><li><strong>도덕적 의무·죄책감·교양을 갖춰야 한다는 두려움</strong>으로만 한 선택은 제외된다. 밀은 <strong>진정으로 감상하는 선호(genuine appreciative preference)</strong> 를 원한다.</li><li>예: <strong>혼자 수동적으로 소비하는 것</strong>과 <strong>함께하는 예술 활동</strong>을 모두 진짜로 경험한 사람들이 <strong>더 힘든데도 후자를 일관되게 선호</strong>한다면, 이 <strong>수렴</strong>은 후자가 <strong>더 높은 질</strong>이라는 <strong>증거</strong>.</li><li><strong>문제</strong>: <strong>무엇이 &quot;충분히 경험한 것&quot;인가</strong>, 그리고 <strong>사회적 위세가 증언을 형성</strong>하는가.</li></ul><h3 id="_3-더-큰-불만을-동반한다는-것을-알면서도-선호한다-—-고급-쾌락의-비용" tabindex="-1">(3) &quot;더 큰 불만을 동반한다는 것을 알면서도&quot; 선호한다 — <strong>고급 쾌락의 비용</strong> <a class="header-anchor" href="#_3-더-큰-불만을-동반한다는-것을-알면서도-선호한다-—-고급-쾌락의-비용" aria-label="Permalink to &quot;(3) &quot;더 큰 불만을 동반한다는 것을 알면서도&quot; 선호한다 — **고급 쾌락의 비용**&quot;">​</a></h3><ul><li>더 높은 쾌락은 <strong>더 많은 어려움·의심·노력·시간·취약성</strong>을 동반할 수 있다. 밀은 <strong>좋은 삶 = 불편이 가장 적은 삶</strong>이라는 등식을 <strong>거부</strong>한다.</li><li>복잡한 능력은 <strong>실패·부정의·불확실성·책임을 자각</strong>하게 하므로 <strong>불만을 낳을 수 있다.</strong></li><li>예: <strong>까다로운 우정</strong>은 <strong>인공 동반자가 없앨 수 있는 갈등</strong>을 만들지만, <strong>상호성·협상·타인의 독립성</strong>이 있기에 <strong>더 가치 있을</strong> 수 있다. → <strong>마찰이 때로는 제거할 비용이 아니라 관계의 구성 요소</strong>인가?</li><li><strong>토론</strong>: 밀은 왜 <strong>더 큰 불만이 더 나은 쾌락과 함께</strong>하는 것을 허용하는가? <strong>가치 있는 어려움</strong>과 <strong>줄여야 할 피할 수 있는 고통</strong>을 어떻게 구분하는가?</li></ul><h3 id="_4-그-대신-다른-쾌락을-어떤-양으로도-포기하지-않으려-한다-—-매우-강한-주장" tabindex="-1">(4) &quot;그 대신 다른 쾌락을 <em>어떤 양으로도</em> 포기하지 않으려 한다&quot; — <strong>매우 강한 주장</strong> <a class="header-anchor" href="#_4-그-대신-다른-쾌락을-어떤-양으로도-포기하지-않으려-한다-—-매우-강한-주장" aria-label="Permalink to &quot;(4) &quot;그 대신 다른 쾌락을 *어떤 양으로도* 포기하지 않으려 한다&quot; — **매우 강한 주장**&quot;">​</a></h3><ul><li><strong>질적 우월성이 매우 많은 양의 저급 쾌락을 능가</strong>할 수 있다. 질은 <strong>양에 얹는 추가 단위가 아니라 비교를 재구성</strong>한다.</li><li>따라서 <strong>모든 선을 하나의 공통 척도에 놓을 수 있다</strong>는 공리주의의 희망에 <strong>압력</strong>을 가한다.</li><li>예: 위험·실패·갈등은 없애지만 <strong>성취·진실·독립적 관계도 없애는 완전히 편안한 시뮬레이션 삶</strong>을 <strong>거부</strong>할 수 있다. 이 거부는 <strong>행위 주체성과 현실이 그 사람이 행복으로 치는 것의 안쪽에 들어와 있음</strong>을 보여 준다. (→ 경험 기계: <a href="./14. 벤담 『서설』 4장 정독 — 쾌락 계산법과 반론(6주차-3).html">14. 벤담 『서설』 4장 정독 — 쾌락 계산법과 반론(6주차-3)</a>)</li></ul><h3 id="_5-우리는-선호되는-즐거움에-질의-우월성을-귀속시킬-자격이-있다-—-결론은-인식론적" tabindex="-1">(5) &quot;우리는 선호되는 즐거움에 질의 우월성을 귀속시킬 <em>자격이 있다</em>&quot; — <strong>결론은 인식론적</strong> <a class="header-anchor" href="#_5-우리는-선호되는-즐거움에-질의-우월성을-귀속시킬-자격이-있다-—-결론은-인식론적" aria-label="Permalink to &quot;(5) &quot;우리는 선호되는 즐거움에 질의 우월성을 귀속시킬 *자격이 있다*&quot; — **결론은 인식론적**&quot;">​</a></h3><ul><li><strong>유능하고, 정보에 기반하며, 안정된 선호가 한 쪽을 강하게 밀 때</strong> 우월성을 귀속시키는 것이 정당화된다. 그러나 결론은 <strong>판단자의 신뢰성과 자유에 조건부</strong>다.</li><li><strong>불평등한 접근, 이데올로기, 장애 장벽, 탈진, 문화적 권위</strong>가 사람들이 <strong>경험하고 비교할 수 있는 것</strong>을 형성한다. → 현대에는 이 시험을 <strong>사회 비판과 짝지어야</strong> 한다: <strong>두 대안이 실제로 모두 가능했는가? 판단을 형성할 시간·교육·안전·자유가 있었는가?</strong> 이 조건이 없다면 우리가 기록하는 건 <strong>질이 아니라 박탈</strong>이다.</li></ul><h2 id="_4-유능한-판단자-시험의-해부-슬라이드-13·18-19쪽-보강-자막-107-130" tabindex="-1">4. 유능한 판단자 시험의 해부 (슬라이드 13·18~19쪽 보강, 자막 107~130) <a class="header-anchor" href="#_4-유능한-판단자-시험의-해부-슬라이드-13·18-19쪽-보강-자막-107-130" aria-label="Permalink to &quot;4. 유능한 판단자 시험의 해부 (슬라이드 13·18~19쪽 보강, 자막 107~130)&quot;">​</a></h2><ul><li><strong>&quot;유능한&quot;은 제도적 자격이 아니다.</strong> 권위는 <strong>비교 경험</strong>에서 나온다. 시험은 <strong>기술적 인증보다 실천적 판단</strong>에 가깝다.</li><li>판단자는 두 쾌락을 <strong>안쪽에서(1인칭)</strong> 알아야 하고 <strong>차이에 주의를 기울일 수 있어야</strong> 한다. 그래서 <strong>1인칭적·비교적</strong>이지만 <strong>단순 주관은 아니다</strong> — 밀은 <strong>자격 있는 많은 비교자 사이의 수렴</strong>을 찾기 때문.</li><li><strong>최소 네 차원</strong>: <strong>① 노출(exposure)</strong> ② <strong>감상 능력(appreciative capacity)</strong> ③ <strong>성찰적 거리(reflective distance)</strong> ④ <strong>강압적 압력으로부터의 자유</strong>. <ul><li>각각 <strong>실패할 수 있다</strong>: 노출이 <strong>피상적</strong>일 수 있고, 감상 능력이 <strong>훈련 부족</strong>으로 막힐 수 있고, 성찰적 거리가 <strong>강박</strong>으로 깨질 수 있다. 능력을 <strong>조건 묶음</strong>으로 보면 시험이 <strong>더 정밀</strong>해지고 <strong>얼마나 까다로운지</strong>도 드러난다.</li></ul></li><li><strong>핵심 구분 — &quot;어떻게 아는가&quot; vs &quot;무엇이 더 낫게 만드는가&quot;</strong><ul><li>유능한 판단자의 증언은 <strong>질적 우월성의 증거</strong>일 수 있어도 <strong>그 우월성의 원천은 아니다.</strong> 판단자들이 한 활동을 선호한다면 선호는 <strong>가치를 만들어 내기보다 드러내는</strong> 것일 수 있다.</li><li>이 구분이 중요한 이유: 아니라면 이론이 <strong>이상화된 선호 만족</strong>으로 무너진다 — <em>유능한 사람이 선호하는 것은 그들이 선호한다는 이유만으로 좋다.</em> 밀의 언어는 종종 <strong>더 강한 것</strong>을 암시한다: <strong>더 높은 능력, 존엄, 행위 주체성, 활동의 구조</strong>가 <strong>왜 그 쾌락이 가치 있는지를 설명</strong>하고, <strong>유능한 선호는 그 가치를 알아보는 인식론적 경로</strong>다.</li><li><strong>밀이 이 설명적 가치를 쾌락주의 안에 둘 수 있는가는 여전히 논쟁 중.</strong></li></ul></li></ul><h2 id="_5-밀에-대한-주요-반론-슬라이드-20쪽" tabindex="-1">5. 밀에 대한 주요 반론 (슬라이드 20쪽) <a class="header-anchor" href="#_5-밀에-대한-주요-반론-슬라이드-20쪽" aria-label="Permalink to &quot;5. 밀에 대한 주요 반론 (슬라이드 20쪽)&quot;">​</a></h2><h3 id="_1-순환성-circularity" tabindex="-1">① 순환성 (circularity) <a class="header-anchor" href="#_1-순환성-circularity" aria-label="Permalink to &quot;① 순환성 (circularity)&quot;">​</a></h3><ul><li><strong>고급 쾌락 = 유능한 판단자가 선호하는 것</strong>이고, <strong>유능한 판단자 = 고급 쾌락을 감상할 수 있는 사람</strong>이라면 <strong>각 개념이 서로를 정의</strong>해 <strong>시험이 순위를 독립적으로 정당화하지 못한다.</strong></li><li><strong>완화책</strong>: <strong>능력을 평가적이 아니라 절차적으로 정의</strong>한다 — <strong>두 선택지에 대한 상당한 경험, 적절한 주의, 특징에 대한 이해, 강요의 부재, 성찰의 기회</strong>. 그러면 판단자가 <strong>우리가 이미 선호하는 결론에 도달했다는 이유로 유능하다고</strong> 말하는 것은 막는다.</li><li><strong>남는 문제</strong>: <strong>감상 능력을 순위를 몰래 끌어들이지 않고 분류할 수 있는가?</strong></li></ul><h3 id="_2-자격-있는-판단자들-사이의-지속적-불일치-→-다원주의-해석" tabindex="-1">② 자격 있는 판단자들 사이의 지속적 불일치 → <strong>다원주의 해석</strong> <a class="header-anchor" href="#_2-자격-있는-판단자들-사이의-지속적-불일치-→-다원주의-해석" aria-label="Permalink to &quot;② 자격 있는 판단자들 사이의 지속적 불일치 → **다원주의 해석**&quot;">​</a></h3><ul><li>불일치가 계속된다면 <strong>가치 있는 인간 삶은 하나의 사다리에 줄 세워지지 않고 복수</strong>일 수 있다. <strong>관조·예술 창작·돌봄·우정·정치 행동·신체적 성취·영적 실천</strong>은 각각 <strong>다른 능력</strong>을 실현한다.</li><li>그러면 시험은 <strong>국소적 비교</strong>(한 활동이 <strong>수동적 대체물보다 질적으로 풍부</strong>하다)는 정당화해도 <strong>철학·음악·양육·스포츠·정치 행동 중 무엇이 보편적으로 우월한지</strong>는 가릴 수 없다. 이 <strong>다원주의적 읽기</strong>는 밀을 <strong>덜 경직</strong>되게 하고 <strong>다양한 번영 형태</strong>와 더 잘 맞게 한다.</li></ul><h3 id="_3-이론적-불안정성-—-쾌락주의-vs-완전주의" tabindex="-1">③ 이론적 불안정성 — <strong>쾌락주의 vs 완전주의</strong> <a class="header-anchor" href="#_3-이론적-불안정성-—-쾌락주의-vs-완전주의" aria-label="Permalink to &quot;③ 이론적 불안정성 — **쾌락주의 vs 완전주의**&quot;">​</a></h3><ul><li>공식 입장: <strong>행복이 궁극 목적, 행복 = 쾌락과 고통의 부재.</strong> 그런데 <strong>고급 쾌락이 매력적인 이유</strong>는 <strong>발달된 능력·자율·존엄·지능·행위 주체성·의미 있는 관계</strong>라는 <strong>완전주의적</strong> 어휘로 말해진다. (완전주의: 어떤 활동은 <strong>쾌적하게 느껴서가 아니라 인간의 탁월함을 실현</strong>하기 때문에 가치 있다.)</li><li><strong>긴장을 날카롭게</strong>: <strong>자율이 자율적 활동이 특별한 종류의 쾌락을 낳기 때문에만 가치 있다면</strong> 밀은 <strong>질적 쾌락주의자</strong>로 남는다. <strong>자율적 활동이 쾌락이 덜할 때도 가치 있다면</strong> 자율은 <strong>독립적 선</strong>이 된다. 둘째 읽기는 밀의 많은 예에 맞지만 <strong>쾌락이 유일한 내재적 가치</strong>라는 주장을 약화시킨다.</li></ul><h3 id="_4-적응적-선호와-불평등한-접근" tabindex="-1">④ 적응적 선호와 불평등한 접근 <a class="header-anchor" href="#_4-적응적-선호와-불평등한-접근" aria-label="Permalink to &quot;④ 적응적 선호와 불평등한 접근&quot;">​</a></h3><ul><li><strong>선택지를 박탈당한 사람</strong>은 <strong>가질 수 없는 것을 원하지 않도록 배운다.</strong> <strong>극심한 시간 압박</strong>에 놓인 사람은 장기 프로젝트에 접근할 수 없어 <strong>즉각적 안도</strong>를 선호할 수 있다. 이런 선호는 <strong>제약에 대한 이해 가능한 반응</strong>이지만 <strong>제약된 쪽이 더 나은 삶의 형태라는 증거</strong>로 자동 취급해선 안 된다.</li><li>밀에게 특히 중요하다: <strong>시험이 경험된 비교에 의존</strong>하므로 <strong>한쪽이 진짜로 가능한 적이 없다면 그 둘 사이의 유능한 판단자가 될 수 없다.</strong></li><li><strong>사회적 함의</strong>: 기관은 <strong>교육·시간·안전·접근성·문화 자원</strong>을 제공해 <strong>결핍이 아니라 실제 기회 아래서</strong> 선호가 형성되게 해야 한다.</li></ul><h3 id="_5-엘리트주의와-고급-저급-어휘의-오용-→-참여-방식-mode-of-engagement-으로-읽기" tabindex="-1">⑤ 엘리트주의와 &quot;고급/저급&quot; 어휘의 오용 → <strong>참여 방식(mode of engagement)</strong> 으로 읽기 <a class="header-anchor" href="#_5-엘리트주의와-고급-저급-어휘의-오용-→-참여-방식-mode-of-engagement-으로-읽기" aria-label="Permalink to &quot;⑤ 엘리트주의와 &quot;고급/저급&quot; 어휘의 오용 → **참여 방식(mode of engagement)** 으로 읽기&quot;">​</a></h3><ul><li>고급·저급의 어휘는 <strong>계급 취향을 도덕적 위계로 바꾸는</strong> 데 오용될 수 있다. <strong>클래식이 대중음악보다</strong>, <strong>형식 철학이 이야기하기보다</strong>, <strong>값비싼 문화 활동이 배타적이라는 이유로</strong> 자동으로 더 높지는 않다. <strong>사회적 위세는 질적 우월성의 필요조건도 충분조건도 아니다.</strong></li><li>기준은 <strong>참여의 구조</strong>: <strong>주의·감각·상상력·상호성·자기 이해·비판적 성찰·행위 주체성.</strong> 이 특성은 <strong>엘리트·대중·가정·공동체·신체·기술</strong> 활동 어디서나 나타난다. <ul><li><strong>춤</strong>: 리듬·규율·기억·표현적 감수성·협력·신체 지능. <strong>가정의 실천</strong>: 기억·돌봄·창의·공동체. <strong>대중문화</strong>: 정교한 해석·동일시·아이러니·비판.</li><li>반대도 가능: <strong>위세 있는 활동</strong>도 <strong>수동적·경쟁적·지위만을 위해</strong> 추구될 수 있다.</li></ul></li><li><strong>범주는 활동의 이름이 아니라 참여 방식을 따라야 한다.</strong> 교육적으로도 유용 — 학생이 <strong>물려받은 문화 서열에 기대지 않고 무엇이 활동을 질적으로 풍부하게 하는지 설명</strong>해야 하므로.</li><li><strong>장애와 접근성</strong>: 활동을 <strong>&quot;정상적인&quot; 몸이나 마음</strong>으로 정의해선 안 된다. 다양한 <strong>감각·인지·의사소통 양식</strong>으로 활동을 만나고 감상할 수 있다. <strong>장애는 접근 형식을 바꿀 뿐 경험의 질을 떨어뜨리지 않는다.</strong> 기관이 <strong>참여 방식을 하나만</strong> 제공하면 <strong>배제가 능력 부족으로 오해</strong>된다. 현대적 밀식 접근은 <strong>접근 불가능한 설계가 만든 무능</strong>과 <strong>감상 역량의 부족</strong>을 구별해야 하고, <strong>자막·낭독·유연한 속도·대체 형식·접근 가능한 공간</strong>은 <strong>가능한 경험의 장을 넓힌다.</strong> 이는 이론에 <strong>외부에서 덧붙인 것이 아니라</strong> 유능한 판단자 시험 자체가 <strong>비교 대상을 접할 공정한 기회</strong>를 전제하기 때문이다.</li></ul><hr><h2 id="_6-현대-적용-슬라이드-21-24쪽" tabindex="-1">6. 현대 적용 (슬라이드 21~24쪽) <a class="header-anchor" href="#_6-현대-적용-슬라이드-21-24쪽" aria-label="Permalink to &quot;6. 현대 적용 (슬라이드 21~24쪽)&quot;">​</a></h2><h3 id="디지털-플랫폼-21쪽" tabindex="-1">디지털 플랫폼 (21쪽) <a class="header-anchor" href="#디지털-플랫폼-21쪽" aria-label="Permalink to &quot;디지털 플랫폼 (21쪽)&quot;">​</a></h3><ul><li>플랫폼은 <strong>시청 시간·재방문 빈도·클릭·공유</strong> 같은 <strong>양</strong>을 최적화한다. 이는 <strong>상호작용이 반복적·몰입적</strong>임은 알려도 경험이 <strong>이해·자율·상호성·성찰적 만족</strong>을 뒷받침하는지는 알려주지 않는다. <strong>밀식 분석</strong>은 <strong>측정된 참여가 웰빙의 좋은 대리 지표인가</strong>를 묻는다.</li><li><strong>끝없는 숏폼 피드</strong>: 즉각성·빈번한 자극·낮은 노력이 있지만 사용자가 나중에 <strong>주의 분산과 밀려난 활동</strong>을 보고할 수 있다. <strong>실제 선택과 성찰적 선호</strong>의 구분이 쓸모 있다 — <strong>행동적으로는 강하지만 성찰적으로는 약한</strong> 반복. <strong>설계 질문</strong>: 플랫폼은 <strong>측정할 수 있는 행동을 증폭</strong>만 해야 하나, 사용자가 <strong>더 성찰적인 선호를 형성하도록 도와야</strong> 하나?</li><li><strong>추천 시스템</strong>: 과거 행동에서 선호를 추론하는데 과거 행동은 <strong>피로·습관·유혹·사회적 압력·제한된 노출</strong>을 반영할 수 있다. <strong>이미 클릭한 것만 최적화</strong>하면 사용자를 <strong>좁은 선호 이력</strong>에 가두고 <strong>발견의 기회</strong>를 줄인다. <strong>질적 설계</strong>는 단순히 더 나은 콘텐츠를 <strong>강요</strong>하지 않는다(<strong>온정주의 위험</strong>). 대신 <strong>선택지를 다양화</strong>하고 <strong>추천 이유를 설명</strong>하며 <strong>장기 선호 설정을 보이게</strong> 하고 <strong>순간적 욕구와 성찰적 목표를 구분</strong>하게 해 <strong>행위 주체성을 보존</strong>한다 → <strong>은밀한 조작이 아니라 정보에 기반한 비교</strong>.</li><li><strong>AI 동반자</strong>: 항상 이용 가능하고, 긍정해 주고, 예측 가능한 위안을 준다. <strong>즉각 만족</strong>으로 재면 많은 인간 관계보다 <strong>더 좋을</strong> 수 있다. 밀의 질적 구분은 <strong>그 만족이 어떤 종류의 관계에 속하는가</strong>를 묻는다. 인간 관계는 <strong>타자의 독립성·의견 불일치 가능성·협상·취약성·상호 인정</strong>을 포함한다. 문제는 안락이 나쁘다거나 인공 동반이 해롭다는 것이 아니라, <strong>타자의 독립성을 제거하는 것이 관계의 질을 바꾸는가</strong>. <strong>상호성과 저항이 관계적 선의 구성 요소</strong>라면 <strong>마찰 없는 만족</strong>에 최적화된 경험은 <strong>양적으로 더 많은 쾌락</strong>을 주면서도 <strong>유능한 비교자가 더 중시하는 차원</strong>을 결여할 수 있다.</li><li><strong>뉴스·정치 피드</strong> (자막 318~332): <strong>분노·공포·새로움·갈등</strong>은 클릭·댓글·반복 확인을 늘린다. 이 지표는 <strong>주의</strong>에 대해 실제적인 것을 말하지만 사용자가 <strong>더 잘 알게 되었는지, 공적 사안을 판단할 능력이 높아졌는지</strong>는 보여주지 않는다. 질-양 구분은 <strong>참여의 양</strong>을 <strong>정치적 이해의 질</strong>과 분리하게 한다. 피드는 <strong>정치적 자극을 많이 주면서 접촉 범위를 좁힐</strong> 수 있고, <strong>짧은 프로그램은 판단에 필요한 역사적·제도적·증거적 배경 없이 감정을 키울</strong> 수 있다. <strong>문제는 감정 자체가 아니다</strong>(<strong>도덕적 분개</strong>는 부정의에 대한 중요한 반응). 문제는 <strong>사용자가 주장을 검증하고 관점을 구성하고 결론을 수정할 수 있는지와 무관하게 반응의 강도·빈도만 최적화</strong>할 때다. 이 틀은 <strong>플랫폼이 시민이 무엇을 읽어야 하는지 은밀히 결정</strong>하는 것에도 반대한다.</li><li><strong>디지털 웰빙 도구</strong> (자막 333~341): 기기 들기·알림·앱 조회 빈도 같은 <strong>분 단위</strong>를 잰다. 그러나 <strong>지지적인 대화 30분 / 주의 깊은 독서 30분 / 강박적 스크롤 30분</strong>은 기록된 시간이 같아도 <strong>질적 구조가 매우 다르다.</strong> <strong>총 화면 시간을 줄이는 시스템</strong>이 <strong>유용하고 의미 있는 활동</strong>을 줄이면서 <strong>해로운 패턴은 남길</strong> 수 있고, 반대로 <strong>총 시간을 늘리는 시스템</strong>이 <strong>교육·창작·중요한 관계 유지</strong>를 돕는다면 복지를 높일 수도 있다. <strong>윤리적 과제</strong>: 양이 가치를 결정한다고 가정하지 말고 <strong>측정되는 활동의 종류</strong>를 따진다.</li></ul><h3 id="교육-22쪽" tabindex="-1">교육 (22쪽) <a class="header-anchor" href="#교육-22쪽" aria-label="Permalink to &quot;교육 (22쪽)&quot;">​</a></h3><ul><li><strong>쾌락과 장기 가치가 자주 갈린다.</strong> 오락은 어려운 독서보다 <strong>쉬워</strong> 보이고 명료한 강의는 까다로운 세미나보다 <strong>편안</strong>하게 느껴진다. <strong>씨름(struggle)</strong> 은 <strong>독립적 판단 능력을 얻는 과정의 일부</strong>일 수 있다.</li><li><strong>발달에 수반되는 불편</strong>과 <strong>무의미하거나 피할 수 있는 고통</strong>을 구별한다(= <strong>구성적 어려움</strong>). <strong>질적 교육 지표</strong>는 학생이 <strong>수업을 즐겼는가/플랫폼에 시간을 썼는가</strong>를 넘어 <strong>더 잘 추론·해석·질문·소통하고 독립적으로 탐구</strong>할 수 있게 됐는지를 묻는다. <strong>만족은 여전히 관련 있지만 교육적 성공의 완전한 정의가 아니라 증거 하나</strong>.</li><li><strong>대학의 지표</strong>: 논문 수·인용 수·학생 평가·수료율·취업 결과 같은 <strong>계량 가능한 대리 지표</strong>는 중요한 패턴을 드러내지만 <strong>행동을 재구성하는 목표</strong>가 될 수 있다. <strong>양이 부분적으로 해석적인 질을 가진 선을 정의하게 해서는 안 된다</strong>: <strong>소논문 여러 편이 변혁적 논문 하나보다</strong> 자동으로 가치 있진 않고, 교육에서 <strong>다룬 내용의 양이 깊은 이해보다</strong> 낫지 않으며, 학문 문화에서 <strong>가시성은 지적 기여와 같지 않다.</strong> 숫자를 증거로 쓰되 <strong>정보에 기반한 질적 판단과 이의 제기의 공간을 보존</strong>한다.</li><li><strong>생성형 AI와 학습</strong> (자막 288~317): 요약·번역·브레인스토밍·재구성의 시간을 줄여 준다. <strong>양적</strong>으로는 이득이 쉽게 설명된다(더 많은 글 처리, 더 빠른 완료, 낮은 노력, 때로 낮은 불안). <strong>밀식 질문</strong>은 <strong>일부 지적 작업이 시스템에 위임될 때 학습 활동의 질</strong>이 어떻게 되는가. <strong>AI 대 비AI</strong>가 아니라 <strong>사용 방식</strong>을 가른다 — <strong>해석을 제거하는 대체물(substitute)</strong> 인가, <strong>더 까다로운 해석을 가능하게 하는 발판(scaffold)</strong> 인가. 답을 받아 베끼면 완성량은 늘어도 <strong>판단 행사는 줄고</strong>, 반론을 만들게 하거나 관점을 비교하거나 논증의 틈을 드러내는 데 쓰면 <strong>행위 주체성이 오히려 늘 수 있다.</strong> <strong>유능한 비교</strong>에는 여러 학습 방식 경험과 <strong>기억 유지·독립성·이해·도움 없이 설명하는 능력</strong>에 대한 성찰이 필요하다. 윤리적 질문은 편리함이 나쁜가가 아니라 <strong>편리함이 학습을 풍부하게 하는 능력을 대체하는가</strong>. 행복 vs 만족: 어려운 철학 논증을 만난 학생은 처음엔 <strong>쉬운 요약</strong>을 선호하는데, 요약은 <strong>불안을 줄이고 즉각적 자신감</strong>을 주지만 <strong>논증을 재구성하고 모호성을 찾고 비판적으로 응답</strong>할 해석 능력을 기르지 못할 수 있다. <ul><li><strong>단, 낭만화하지 말 것</strong>: <strong>어려움 자체가 높은 질의 표지는 아니다.</strong> 엉성한 수업, 접근 불가능한 언어, 임의의 업무량, 막을 수 있는 혼란은 그냥 <strong>에너지 낭비</strong>. 질문은 <strong>어려움이 역량 발달에 내재적인가, 결함 있는 조건이 부과한 것인가</strong>. 교사는 <strong>피할 수 있는 장벽</strong>은 줄이고 <strong>학생이 직접 해야 하는 지적 작업</strong>은 보존할 수 있다 → <strong>고통과 동일시하지 않고 엄밀성(rigor)을 정의</strong>.</li></ul></li></ul><h3 id="직장과-지표-23쪽" tabindex="-1">직장과 지표 (23쪽) <a class="header-anchor" href="#직장과-지표-23쪽" aria-label="Permalink to &quot;직장과 지표 (23쪽)&quot;">​</a></h3><ul><li><strong>일</strong>은 임금·시간·산출·고용률로 <strong>양적</strong>으로 평가된다. 필수적이지만 <strong>불완전</strong>하다. <strong>일의 질</strong>은 <strong>안정성·자율·기술 발달·사회적 인정·의미 있는 협력·자기 삶을 계획할 능력</strong>과 관련된다. 일자리는 <strong>예측 불가능성과 지속적 감시</strong>로 <strong>행위 주체성을 해치면서 소득</strong>을 줄 수 있다. (<strong>모두가 일을 통해 자아실현을 추구해야 한다는 뜻은 아니다.</strong> <strong>휴식과 물질적 안정도 진짜 선</strong>.) 요점은 <strong>복지 정책이 어떤 유급 시간도 다른 시간과 동등하게 취급해선 안 된다</strong>는 것 — 일의 구조가 사람들이 <strong>소중히 여기는 능력을 개발·행사하지 못하게</strong> 체계적으로 막으면 그 <strong>복지 손실은 총소득 데이터에 보이지 않을</strong> 수 있다.</li><li><strong>감시 지표</strong>: 응답 시간·작업 완료·고객 평가·소프트웨어 접속 시간은 <strong>병목을 찾고 산출의 증거</strong>를 줄 수 있으나 <strong>판단·협력·창의·멘토링·신뢰·재량 행사 능력</strong>을 놓친다. <strong>눈에 보이는 단위는 적게 만들지만 어려운 사례를 풀고 동료를 돕고 미래 오류를 막는 노동자</strong>가 있고, 반대로 <strong>쉬운 작업만 고르거나 중요하지만 측정이 안 되는 일을 피해</strong> 기록 산출을 극대화하는 노동자가 있다. <strong>지표가 목표가 되면 가치 있는 것보다 셀 수 있는 것을 중심으로 행동이 재편</strong>된다(= 밀이 &quot;양만으로는 평가 못 한다&quot;고 할 때의 문제의 현대판). <strong>지속적 감시는 임금과 산출이 안정적일 때도 자율을 줄이고 불안을 만든다.</strong> 공리주의 분석은 <strong>생산성 효과와 감시 체제 아래의 행위 주체성의 질</strong>을 모두 포함해야 하고, 비교는 <strong>얼마나 많은 일이 생산되는가</strong>뿐 아니라 <strong>그 시스템이 그 아래 있는 사람들에게 어떤 노동의 삶을 만드는가</strong>를 물어야 한다.</li><li><strong>의료</strong> (자막 263~266): <strong>신뢰·소통·존엄·돌봄의 연속성·환자가 결정을 이해하고 참여하는 능력.</strong> <strong>짧은 진료</strong>는 처리량에서 효율적이지만 환자를 <strong>혼란스럽고 말하지 못한 채</strong> 두고, <strong>긴 진료</strong>는 시간당 <strong>적은 수</strong>를 볼 수 있어도 <strong>이해와 행위 주체성</strong>을 높일 수 있다. 윤리 문제는 <strong>한 지표가 모든 경우를 해결한다고 가정하지 않고</strong> 이 가치들을 <strong>비교</strong>하는 것.</li></ul><h3 id="사회와-정책-24쪽" tabindex="-1">사회와 정책 (24쪽) <a class="header-anchor" href="#사회와-정책-24쪽" aria-label="Permalink to &quot;사회와 정책 (24쪽)&quot;">​</a></h3><ul><li><strong>소비문화</strong>는 <strong>웰빙을 소비 증가와 동일시</strong>하는 경우가 많다. 질적 틀은 그 그림을 깬다: <strong>지식·창의·견습·돌봄·공공 참여·숙련된 실천</strong>은 <strong>물질적 처리량에 비례하지 않는 만족</strong>을 줄 수 있어 <strong>더 낮은 소비 수준 없이도 더 풍부한 복지 개념</strong>을 위한 개념적 공간을 낸다. <strong>단, 도덕 설교가 되어선 안 된다.</strong> <strong>시간·공공 공간·교육·안전·생태적 안정에의 접근 자체가 고르지 않다.</strong> 질적 웰빙 설명은 <strong>사회적 조건과 연결</strong>되어야 하며, 아니면 &quot;더 단순한 즐거움을 택하라&quot;는 요구가 <strong>특권 집단은 물질적 풍요를 유지한 채 불리한 집단에게 박탈을 받아들이라고 요구</strong>하는 방식이 될 수 있다.</li><li><strong>민주주의</strong> (자막 270~278): 사회는 <strong>참여를 좁혀서 눈에 보이는 갈등을 줄일</strong> 수 있고, <strong>순전히 안락 중심의 관점</strong>에서는 <strong>조용함이 복지처럼</strong> 보인다. 밀의 질적 관점은 <strong>정치적 행위 주체성·공적 추론·비판의 자유</strong>가 <strong>더 풍부한 인간 삶의 구성 요소</strong>인지 묻는다. 민주적 참여는 <strong>좌절스럽고 복잡</strong>해도 <strong>수동적 안정이 쓰지 않는 능력</strong>을 행사한다.</li><li><strong>공공 정책과 분배</strong> (자막 276~287): <strong>작은 이익이 많이 모이면 소수에게 부과된 심각한 부담을 가릴</strong> 수 있다. 밀의 이론은 <strong>복지 분석을 풍부하게</strong> 하지만 <strong>권리·분배·동의의 문제를 스스로 풀지 못한다.</strong> 이것들은 <strong>단순한 추가나 총만족이 아니라 집계에 대한 제약</strong>으로 작동해야 할 수도 있다. <strong>분배가 도덕적으로 중요한 이유</strong>: <strong>심각한 고통이 유리한 총합 안에 숨겨질</strong> 수 있기 때문. 또 <strong>자원이 불평등한 사람들은 더 높은 능력을 기르는 활동에의 접근도 불평등</strong>하다 → 불평등은 <strong>복지의 결과와 선호의 인식론적 조건 모두</strong>에 영향을 준다. <strong>교육·여가·안전한 공공 공간·문화적 접근이 있는 집단</strong>과 <strong>고된 노동 뒤의 즉각적 위안만 있는 집단</strong>의 <strong>표현된 선호를 동등한 기회에서 나온 것처럼 비교하는 것은 오독</strong>. 사회 정책은 <strong>현재 만족뿐 아니라 능력 형성(capability formation)</strong> 을 고려해야 한다.</li></ul><hr><h2 id="_7-밀식-분석-5단계-슬라이드-25쪽-자막은-356-363부터-끊긴-부분-포함" tabindex="-1">7. 밀식 분석 5단계 (슬라이드 25쪽; 자막은 356~363부터 끊긴 부분 포함) <a class="header-anchor" href="#_7-밀식-분석-5단계-슬라이드-25쪽-자막은-356-363부터-끊긴-부분-포함" aria-label="Permalink to &quot;7. 밀식 분석 5단계 (슬라이드 25쪽; 자막은 356~363부터 끊긴 부분 포함)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>단계</th><th>내용</th></tr></thead><tbody><tr><td><strong>① 차원 분리</strong></td><td><strong>양적 차원</strong>과 <strong>질적 차원(행위 주체성·존엄)</strong> 을 나눈다</td></tr><tr><td><strong>② 영향 지도화</strong></td><td>관련된 <strong>사람들</strong>과 <strong>시간적 결과</strong>를 파악한다</td></tr><tr><td><strong>③ 선호 탐침</strong></td><td>선택이 <strong>정보에 기반</strong>했는가, 아니면 <strong>강요·제약·탈진·중독·불평등한 접근</strong>에 의한 것인가</td></tr><tr><td><strong>④ 분배 점검</strong></td><td><strong>누가 이익을, 누가 부담을</strong> 지는가. <strong>유리한 집계 안에 심각한 해악</strong>이 숨어 있지 않은가</td></tr><tr><td><strong>⑤ 온정주의 점검</strong></td><td>제안된 대응이 <strong>기회와 성찰을 넓히는가</strong>, 아니면 <strong>하나의 권위적 좋은 삶 개념을 강제</strong>하는가</td></tr></tbody></table><blockquote><p>슬라이드 25쪽의 순서는 ① 차원 분리 → ② 분배 점검 → ③ 영향 지도 → ④ 온정주의 점검 → ⑤ 선호 탐침이며, 자막의 설명 순서(영향 → 선호 → 분배 → 온정주의)와 약간 다르다. 위 표는 <strong>자막에서 말한 순서</strong>를 따랐고 시험 답안에서는 <strong>슬라이드 순서와 설명 순서 모두</strong> 같은 5요소라고 이해하면 된다.</p></blockquote><p><strong>경고 (두 오류)</strong>: ① 문화적 위세만으로 &quot;higher&quot;라 부르기 ② 숫자의 의미를 묻지 않는 수치 극대화.</p><hr><h2 id="_8-철학자-비교와-최종-종합-슬라이드-26쪽-자막-369-404" tabindex="-1">8. 철학자 비교와 최종 종합 (슬라이드 26쪽, 자막 369~404) <a class="header-anchor" href="#_8-철학자-비교와-최종-종합-슬라이드-26쪽-자막-369-404" aria-label="Permalink to &quot;8. 철학자 비교와 최종 종합 (슬라이드 26쪽, 자막 369~404)&quot;">​</a></h2><h3 id="한눈에-비교" tabindex="-1">한눈에 비교 <a class="header-anchor" href="#한눈에-비교" aria-label="Permalink to &quot;한눈에 비교&quot;">​</a></h3><ul><li><strong>벤담</strong>: <strong>쾌락·고통의 양과 분포</strong>를 강조.</li><li><strong>밀</strong>: <strong>결과는 유지</strong>하되 <strong>쾌락 사이의 질적 구분</strong>을 추가. 또한 <strong>인간의 번영과 함양된 덕</strong>과 관련해 활동을 평가해 <strong>활동의 형태를 중심</strong>에 둔다.</li><li><strong>칸트</strong>: <strong>도덕적 가치를 행복이 아니라 이성적 행위 능력과 의무</strong>에 둔다.</li><li><strong>밀은 불안정하지만 생산적인 중간 지점</strong>: <strong>벤담처럼 복지 결과에 헌신</strong>하고, <strong>아리스토텔레스처럼 발달된 능력과 더 풍부한 활동 형태</strong>에 관심을 두며, <strong>칸트처럼 존엄의 언어</strong>를 쓰지만 <strong>존엄을 행복 위의 독립적 도덕 토대가 아니라 행복 </strong>안<strong>에 놓으려</strong> 한다. 이 <strong>혼종성(hybridity)</strong> 이 질적 공리주의의 <strong>힘과 어려움</strong>을 모두 설명한다.</li></ul><h3 id="최종-종합" tabindex="-1">최종 종합 <a class="header-anchor" href="#최종-종합" aria-label="Permalink to &quot;최종 종합&quot;">​</a></h3><ul><li><strong>밀은 효용 원리를 버리지 않는다. 행복이 무엇을 뜻할 수 있어야 하는지를 바꾼다.</strong> 인간 복지는 <strong>쾌적한 감각의 단순 총합으로 표현될 수 없다</strong> — 사람은 <strong>발달된 능력·관계·프로젝트·행위 주체성</strong>을 통해 쾌락을 경험하기 때문. <strong>질의 차이는 어떤 적절한 행복 이론에도 내부 문제</strong>가 된다.</li><li><strong>얻은 것</strong>: <strong>철학적 깊이</strong>. <strong>치른 값</strong>: <strong>이론적 불안정성</strong> — 유능한 판단자 시험은 <strong>엘리트주의나 순환</strong>이 될 수 있고, <strong>불평등한 사회 조건</strong>이 선호의 증거를 복잡하게 하며, 무엇보다 <strong>존엄·자율·진실·발달된 능력</strong>은 <strong>쾌락으로 환원하기 어려운 가치</strong>로 기능할 수 있다.</li><li><strong>밀의 지속적 기여는 이중적</strong>: <strong>측정이 왜 중요한지</strong>와 <strong>측정만으로는 인간 번영을 정의할 수 없는 이유</strong> 둘 다를 보여 준다.</li></ul><h3 id="밀의-논증-재구성-6단계-자막-405-415-—-시험에서-그대로-쓸-수-있는-골격" tabindex="-1">밀의 논증 재구성 (6단계, 자막 405~415 — <strong>시험에서 그대로 쓸 수 있는 골격</strong>) <a class="header-anchor" href="#밀의-논증-재구성-6단계-자막-405-415-—-시험에서-그대로-쓸-수-있는-골격" aria-label="Permalink to &quot;밀의 논증 재구성 (6단계, 자막 405~415 — **시험에서 그대로 쓸 수 있는 골격**)&quot;">​</a></h3><ol><li><strong>쾌락은 완전히 동질적이지 않고 이질적(heterogeneous)</strong> 이다.</li><li><strong>일상의 평가는 이미 양뿐 아니라 질도 쓴다.</strong></li><li><strong>두 대안을 모두 경험한 사람</strong>이 비교하기에 더 유리한 위치에 있다.</li><li><strong>자격 있는 비교자는 더 큰 불만이 따르는데도 한 쾌락을 선호</strong>할 수 있다.</li><li>그들은 <strong>다른 쪽의 어떤 양과도 그것을 맞바꾸기를 거부</strong>할 수 있다.</li><li>이런 <strong>정보에 기반한 선호의 패턴이 질적 우월성의 귀속을 정당화</strong>한다.</li></ol><p><strong>이 재구성은 반론이 어디를 겨냥해야 하는지를 밝힌다</strong>: 비평가는 <strong>① 이질성을 부정</strong>하거나, <strong>② 유능한 비교자의 신뢰성을 문제 삼거나</strong>, <strong>③ 선호에서 우월성으로 가는 강한 추론을 거부</strong>하거나, <strong>④ 결론이 쾌락주의를 버리는 것</strong>이라고 주장할 수 있다.</p><hr><h2 id="시험-대비-핵심-키워드-이-노트-기준" tabindex="-1">시험 대비 핵심 키워드 (이 노트 기준) <a class="header-anchor" href="#시험-대비-핵심-키워드-이-노트-기준" aria-label="Permalink to &quot;시험 대비 핵심 키워드 (이 노트 기준)&quot;">​</a></h2><ul><li>밀의 <strong>연속성</strong>: 결과주의·<strong>최대 행복 원리</strong>·쾌락주의·<strong>공정성</strong> / 밀의 <strong>수정</strong>: 쾌락의 <strong>질</strong>(양만으로는 부족)</li><li><strong>&quot;돼지에게나 어울리는 교리&quot;</strong> 반론 → <strong>발달된 능력</strong> → 질</li><li><strong>상황적 이점 vs 내재적 우월성</strong> (안전·지속·저비용 vs 경험의 종류)</li><li><strong>유능한 판단자 시험</strong>: 두 쾌락 <strong>경험</strong>, <strong>확정된 선호</strong>, <strong>도덕적 의무감 배제</strong>, 네 차원(<strong>노출·감상 능력·성찰적 거리·강압으로부터 자유</strong>), <strong>&quot;어떻게 아는가&quot; vs &quot;무엇이 더 낫게 하는가&quot;</strong></li><li><strong>더 큰 불만에도 선호</strong>, <strong>어떤 양과도 맞바꾸지 않음</strong>(질이 비교를 재구성)</li><li>반론: <strong>엘리트주의, 순환성, 적응적 선호(불평등한 접근), 이론적 불안정성(쾌락주의-완전주의), 자격 있는 판단자들의 불일치(다원주의)</strong></li><li><strong>행복 vs 만족</strong>, <strong>불만족한 소크라테스 vs 만족한 바보</strong>, <strong>존엄</strong></li><li>적용: <strong>플랫폼(참여≠웰빙)</strong>, <strong>교육(구성적 어려움)</strong>, <strong>직장(감시·지표)</strong>, <strong>AI(대체물 vs 발판)</strong>, <strong>정책(권리·분배는 집계에 대한 제약)</strong></li><li><strong>밀식 분석 5단계</strong>, <strong>두 오류</strong></li></ul><p><em>출처: 2026-10-19 윤리학 001분반 7주차(이어지는 시간) TransLive 자막(윤지영 교수)과 <code>26-2 Ethics-Week-7.pdf</code> 슬라이드를 바탕으로 직접 재구성. 자막 전문은 <a href="./Raw-Transcripts/2026-10-19_week7-2.html">Raw-Transcripts</a>에 보관. 자막의 &quot;MEAL/Mills/million analysis&quot;는 모두 Mill(밀)/Millian analysis(밀식 분석)의 오인식이라 바로잡았다.</em></p>',65)])])}const _=r(g,[["render",l]]);export{c as __pageData,_ as default};
